-- Canonical identity facts, part of the complete schema 11 baseline.
CREATE TABLE organization_labels(id INTEGER PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,name TEXT NOT NULL,is_active INTEGER NOT NULL CHECK(is_active IN (0,1)));
CREATE TABLE persons(id INTEGER PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,full_name TEXT NOT NULL,employee_number TEXT NOT NULL,status TEXT NOT NULL,employment_type TEXT NOT NULL,hire_date TEXT NOT NULL,probation_ends_on TEXT,contract_ends_on TEXT);
CREATE TABLE accounts(id INTEGER PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,username TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,role_code TEXT NOT NULL,is_active INTEGER NOT NULL CHECK(is_active IN (0,1)),template_id INTEGER REFERENCES permission_schemes(id),use_role_defaults INTEGER NOT NULL CHECK(use_role_defaults IN (0,1)),source_mode TEXT NOT NULL CHECK(source_mode IN ('Independent','Template')));
CREATE TABLE account_grants(account_id INTEGER NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,resource_key TEXT NOT NULL,action TEXT NOT NULL,data_scope TEXT NOT NULL CHECK(data_scope IN ('own','department','company','all')),PRIMARY KEY(account_id,resource_key,action));
CREATE TABLE identity_projection(id INTEGER PRIMARY KEY REFERENCES records(id) ON DELETE CASCADE,body TEXT NOT NULL);
CREATE VIEW identity_facts AS SELECT r.id,r.kind,r.identity,r.version,r.owner_id,r.company,r.department,r.search_text,
CASE r.kind WHEN 'companies' THEN json_set(r.body,'$.code',u.code,'$.name',l.name,'$.isActive',json(CASE WHEN l.is_active=1 THEN 'true' ELSE 'false' END),'$.parentCompanyCode',COALESCE((SELECT code FROM organization_units a WHERE a.id=u.parent_id),''),'$.unitKind',u.unit_kind,'$.executiveAppointmentId',(SELECT appointment_id FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Primary'),'$.additionalLeaders',json((SELECT json_group_array(json(value)) FROM (SELECT json_object('employeeId',(SELECT person_id FROM personnel_memberships a WHERE a.id=d.appointment_id),'appointmentId',d.appointment_id,'workflowKinds',json(d.workflow_kinds)) AS value FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Delegate' ORDER BY d.appointment_id) q))) WHEN 'departments' THEN json_set(r.body,'$.code',dep.code,'$.name',l.name,'$.isActive',json(CASE WHEN l.is_active=1 THEN 'true' ELSE 'false' END),'$.companyCode',(SELECT code FROM organization_units a WHERE a.id=dep.unit_id),'$.parentCode',COALESCE((SELECT code FROM organization_departments a WHERE a.id=dep.parent_id),''),'$.managerAppointmentId',(SELECT appointment_id FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Primary'),'$.additionalLeaders',json((SELECT json_group_array(json(value)) FROM (SELECT json_object('employeeId',(SELECT person_id FROM personnel_memberships a WHERE a.id=d.appointment_id),'appointmentId',d.appointment_id,'workflowKinds',json(d.workflow_kinds)) AS value FROM organization_duties d WHERE d.organization_id=r.id AND d.duty_kind='Delegate' ORDER BY d.appointment_id) q))) WHEN 'people' THEN json_set(r.body,'$.fullName',p.full_name,'$.profile.fullName',p.full_name,'$.employeeNumber',p.employee_number,'$.status',p.status,'$.employmentType',p.employment_type,'$.hireDate',p.hire_date,'$.probationEndsOn',p.probation_ends_on,'$.contractEndsOn',p.contract_ends_on,'$.jobTitle',(SELECT job_title FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1),'$.organization',json(json_object('primaryAssignmentId',(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1),'primaryStartsOn',(SELECT starts_on FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1),'managerAssignmentId',(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Line'),'functionalManagerAssignmentIds',json((SELECT json_group_array(value) FROM (SELECT f.manager_appointment_id AS value FROM reporting_relations f WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Functional' ORDER BY f.manager_appointment_id) q)),'managerEmployeeId',(SELECT person_id FROM personnel_memberships m WHERE m.id=(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Line')),'functionalManagerEmployeeIds',json((SELECT json_group_array(json(value)) FROM (SELECT m.person_id AS value FROM reporting_relations f JOIN personnel_memberships m ON m.id=f.manager_appointment_id WHERE f.appointment_id=(SELECT id FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1) AND f.relation_type='Functional' ORDER BY m.person_id) q)),'additionalAssignments',json((SELECT json_group_array(json(value)) FROM (SELECT json_object('id',m.id,'companyCode',m.company,'departmentId',m.department,'jobTitle',m.job_title,'startsOn',m.starts_on,'endsOn',m.ends_on,'managerAssignmentId',(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=m.id AND f.relation_type='Line'),'functionalManagerAssignmentIds',json((SELECT json_group_array(manager_appointment_id) FROM (SELECT f.manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=m.id AND f.relation_type='Functional' ORDER BY f.manager_appointment_id))),'managerEmployeeId',(SELECT person_id FROM personnel_memberships a WHERE a.id=(SELECT manager_appointment_id FROM reporting_relations f WHERE f.appointment_id=m.id AND f.relation_type='Line')),'functionalManagerEmployeeIds',json((SELECT json_group_array(json(value)) FROM (SELECT a.person_id AS value FROM reporting_relations f JOIN personnel_memberships a ON a.id=f.manager_appointment_id WHERE f.appointment_id=m.id AND f.relation_type='Functional' ORDER BY a.person_id) q))) AS value FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=0 ORDER BY m.starts_on,m.id) q)))),'$.account',json(CASE WHEN EXISTS(SELECT 1 FROM personnel_accounts a WHERE a.person_id=r.id) THEN json_object('id',(SELECT user_id FROM personnel_accounts a WHERE a.person_id=r.id)) ELSE NULL END),'$.employee',json(json_set(COALESCE(r.body->>'employee','{}'),'$.id',r.id,'$.fullName',p.full_name,'$.employeeNumber',p.employee_number,'$.status',p.status,'$.employmentType',p.employment_type,'$.hireDate',p.hire_date,'$.jobTitle',(SELECT job_title FROM personnel_memberships m WHERE m.person_id=r.id AND m.is_primary=1),'$.departmentId',r.department))) WHEN 'users' THEN json_set(r.body,'$.username',a.username,'$.fullName',a.full_name,'$.role',a.role_code,'$.isActive',json(CASE WHEN a.is_active=1 THEN 'true' ELSE 'false' END),'$.permissionTemplateId',a.template_id,'$.permissionGrants',json(CASE WHEN a.source_mode='Independent' THEN (SELECT json_group_array(json(value)) FROM (SELECT json_object('resourceKey',g.resource_key,'action',g.action,'dataScope',g.data_scope) AS value FROM account_grants g WHERE g.account_id=r.id ORDER BY g.resource_key,g.action) q) ELSE NULL END),'$.useRoleDefaults',json(CASE WHEN a.use_role_defaults=1 THEN 'true' ELSE 'false' END)) WHEN 'permission-templates' THEN json_set(r.body,'$.ownerUnitId',s.owner_unit_id,'$.code',s.code) WHEN 'unit-access' THEN json_set(r.body,'$.userId',ur.user_id,'$.companyCode',(SELECT code FROM organization_units a WHERE a.id=ur.unit_id),'$.appointmentId',ur.appointment_id,'$.mode',ur.mode,'$.isActive',json(CASE WHEN ur.is_active=1 THEN 'true' ELSE 'false' END),'$.permissionTemplateId',ur.template_id,'$.authorityRoleId',ur.authority_role_id,'$.permissionGrants',json(CASE WHEN ur.source_mode='Independent' THEN (SELECT json_group_array(json(value)) FROM (SELECT json_object('resourceKey',g.resource_key,'action',g.action,'dataScope',g.data_scope) AS value FROM unit_access_grants g WHERE g.role_id=r.id ORDER BY g.resource_key,g.action) q) ELSE NULL END)) ELSE r.body END AS body
FROM records r
LEFT JOIN organization_units u ON u.id=r.id
LEFT JOIN organization_departments dep ON dep.id=r.id
LEFT JOIN organization_labels l ON l.id=r.id
LEFT JOIN persons p ON p.id=r.id
LEFT JOIN accounts a ON a.id=r.id
LEFT JOIN permission_schemes s ON s.id=r.id
LEFT JOIN unit_access_roles ur ON ur.id=r.id;
CREATE VIEW identity_rows AS SELECT r.id,r.kind,r.identity,r.version,r.owner_id,r.company,r.department,r.search_text,
CASE WHEN r.kind IN ('companies','departments','people','users','permission-templates','unit-access') THEN p.body ELSE r.body END AS body
FROM records r LEFT JOIN identity_projection p ON p.id=r.id;
